from research_helpers import *
a=ev('https://ir.wavelifesciences.com/news-releases/news-release-details/wave-life-sciences-reports-second-quarter-2026-financial-results','August 2026 issuer identifies five current named programs WVE-007/006/008/N531/003 and platform portfolio. Additional undisclosed targets not fabricated.')
b=ev('https://ir.wavelifesciences.com/news-releases/news-release-details/wave-life-sciences-initiates-phase-2a-combination-trial-wve-007','September 2026 issuer confirms WVE-007 clinical development; tirzepatide belongs to partner and is not a separate Wave-owned product.')
c=ev('https://ir.wavelifesciences.com/node/9206/html','Issuer confirms March 2021 discontinuation of WVE-120101 and WVE-120102, distinct first-generation Huntington disease candidates.')
d=ev('https://ir.wavelifesciences.com/news-releases/news-release-details/wave-life-sciences-announces-discontinuation-suvodirsen','Issuer confirms December 2019 discontinuation of suvodirsen/WVE-210201.')
e=ev('https://ir.wavelifesciences.com/news-releases/news-release-details/wave-life-sciences-announces-topline-results-phase-1b2a-focus-c9','Issuer confirms May 2023 WVE-004 discontinuation after no clinical benefit.')
f=ev('https://www.sec.gov/Archives/edgar/data/1631574/000119312526324917/d177737dex992.htm','Current issuer presentation distinguishes SpiNA RNA interference, AIMer RNA editing and broader stereopure oligonucleotide chemistry.')
products=[]
for name,desc,life in [('WVE-007','INHBE-targeted GalNAc siRNA clinical candidate for obesity.','development'),('WVE-006','SERPINA1 RNA editing clinical candidate for alpha-1 antitrypsin deficiency.','development'),('WVE-008','PNPLA3 I148M RNA editing candidate for liver disease; clinical initiation not inferred from planned filing.','research'),('WVE-N531','Exon 53-skipping oligonucleotide clinical candidate for Duchenne muscular dystrophy.','development'),('WVE-003','Allele-selective mutant huntingtin oligonucleotide candidate; further pivotal advancement contingent on development strategy.','development')]:
 products.append(p(name,desc,a,life,evidence=[a,b] if name=='WVE-007' else [a]))
for name in ['WVE-120101','WVE-120102']:
 products.append(p(name,'First-generation allele-selective Huntington disease oligonucleotide program stopped in March 2021.',c,'discontinued'))
products += [p('Suvodirsen','Exon 51-skipping oligonucleotide program for Duchenne muscular dystrophy stopped in December 2019.',d,'discontinued',aliases=['WVE-210201']),p('WVE-004','C9orf72-targeted oligonucleotide program for ALS/frontotemporal dementia stopped in May 2023.',e,'discontinued')]
for name,desc in [('Wave AIMer RNA editing','ADAR-mediated RNA editing therapeutic discovery technology.'),('Wave SpiNA RNA interference','Stereopure interfering nucleic acid technology for gene silencing.'),('Wave PRISM stereopure oligonucleotide platform','Discovery platform integrating stereopure nucleic acid chemistry and design for RNA medicines.')]:
 products.append(p(name,desc,f,'research',typ='technology',sub='research_tools'))
co=dict(company_id='cmp_09f922c8-7c02-4472-89a1-6548fcb51d63',products=products,evidence=[a,b,c,d,e,f],status='partial',coverage_note='Five current named candidates, four explicitly discontinued legacy candidates and three named technologies recorded. Partial: detailed 2026 WVE-003/N531 advancement, later WVE-008 CTA outcome and additional legacy preclinical codes need review. Undisclosed partner targets and planned dosing milestones not invented as completed products/events.')
(out/'batch-0223.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
